// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Exact AA-DOMAINS preimages shared by typed artist owners and their coordinator.
library StreamArtistHashes {
    struct AttestationRecordPreimage {
        bytes32 domain;
        uint256 chainId;
        address registry;
        address core;
        uint256 collectionId;
        uint8 subjectKind;
        bytes32 subjectId;
        bytes32 subjectStateHash;
        bytes32 schemaId;
        bytes32 statementHash;
        bytes32 statementURIHash;
        bytes32 artistId;
        address signer;
        uint8 authorityClass;
        uint256 nonce;
        uint64 signedAt;
    }

    struct Environment {
        uint256 chainId;
        address registry;
        address core;
        address manager;
    }

    function emptyCollaborators() internal pure returns (bytes32) {
        StreamArtistOnboardingTypes.CollaboratorRecord[] memory items =
            new StreamArtistOnboardingTypes.CollaboratorRecord[](0);
        return keccak256(abi.encode(keccak256("6529STREAM_ARTIST_COLLABORATOR_SET_V1"), items));
    }

    function emptyCapabilities() internal pure returns (bytes32) {
        StreamArtistOnboardingTypes.CapabilityPolicyOverride[] memory items =
            new StreamArtistOnboardingTypes.CapabilityPolicyOverride[](0);
        return keccak256(abi.encode(keccak256("6529STREAM_ARTIST_CAPABILITY_POLICY_SET_V1"), items));
    }

    function identity(Environment memory e, address artist, bytes32 document, uint256 nonce)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ID_V1"), e.chainId, e.registry, artist, document, nonce
            )
        );
    }

    function binding(
        Environment memory e,
        uint256 collectionId,
        StreamArtistOnboardingTypes.Binding memory b
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_BINDING_V1"),
                e.chainId,
                e.registry,
                e.core,
                collectionId,
                b.generation,
                b.artistId,
                b.artistAddress,
                b.identityRecordHash,
                b.consentMode,
                b.saleConsentScope,
                b.registryImmutabilityElection,
                uint8(0),
                uint32(0),
                emptyCollaborators(),
                emptyCapabilities()
            )
        );
    }

    function typed(Environment memory e, bytes32 structHash) internal pure returns (bytes32) {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamArtistRegistry"),
                keccak256("1"),
                e.chainId,
                e.registry
            )
        );
        return keccak256(abi.encodePacked("\x19\x01", domain, structHash));
    }

    function acceptanceDigest(
        Environment memory e,
        uint256 collectionId,
        StreamArtistOnboardingTypes.Binding memory b,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistAcceptance(address core,uint256 collectionId,uint64 bindingGeneration,bytes32 bindingHash,bytes32 identityRecordHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    collectionId,
                    b.generation,
                    b.bindingHash,
                    b.identityRecordHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function acceptanceRecord(
        Environment memory e,
        uint256 collectionId,
        StreamArtistOnboardingTypes.Binding memory b,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ACCEPTANCE_RECORD_V1"),
                e.chainId,
                e.registry,
                e.core,
                collectionId,
                b.generation,
                b.bindingHash,
                uint8(1),
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function acceptanceRecordForAuthority(
        Environment memory e,
        uint256 collectionId,
        StreamArtistOnboardingTypes.Binding memory b,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ACCEPTANCE_RECORD_V1"),
                e.chainId,
                e.registry,
                e.core,
                collectionId,
                b.generation,
                b.bindingHash,
                uint8(1),
                signer,
                authorityClass,
                nonce,
                signedAt
            )
        );
    }

    function policyDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.PolicyConsent memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistPolicyConsent(address core,address mintManager,uint256 collectionId,bytes32 phaseId,bytes32 policyHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    e.manager,
                    p.collectionId,
                    p.phaseId,
                    p.policyHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function policyRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.PolicyConsent memory p,
        bytes32 artistId,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_POLICY_CONSENT_RECORD_V1"),
                e.chainId,
                e.registry,
                e.manager,
                p.collectionId,
                p.phaseId,
                p.policyHash,
                artistId,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function policyRecordForAuthority(
        Environment memory e,
        StreamArtistOnboardingTypes.PolicyConsent memory p,
        bytes32 artistId,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_POLICY_CONSENT_RECORD_V1"),
                e.chainId,
                e.registry,
                e.manager,
                p.collectionId,
                p.phaseId,
                p.policyHash,
                artistId,
                signer,
                authorityClass,
                nonce,
                signedAt
            )
        );
    }

    function economicsDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.EconomicsConsent memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistEconomicsConsent(address core,address resolver,bytes32 revenueClass,uint8 scope,uint256 scopeId,bytes32 assignmentHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    p.resolver,
                    p.revenueClass,
                    p.scope,
                    p.scopeId,
                    p.assignmentHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function economicsRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.EconomicsConsent memory p,
        bytes32 designation,
        bytes32 artistId,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ECONOMICS_CONSENT_RECORD_V1"),
                e.chainId,
                e.registry,
                p.resolver,
                p.revenueClass,
                p.scope,
                p.scopeId,
                p.assignmentHash,
                designation,
                artistId,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function payoutDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.PayoutDesignation memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistPayoutDesignation(bytes32 artistId,address payoutAccount,bytes32 previousDesignationRecordHash,uint256 nonce,uint64 signedAt)"
                    ),
                    p.artistId,
                    p.payoutAccount,
                    p.previousDesignationRecordHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function royaltyFreezeDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.RoyaltyFreeze memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistRoyaltyFreeze(address core,address resolver,uint256 collectionId,bytes32 revenueClass,bytes32 expectedAssignmentHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    p.resolver,
                    p.collectionId,
                    p.revenueClass,
                    p.expectedAssignmentHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function royaltyFreezeRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.RoyaltyFreeze memory p,
        bytes32 artistId,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ROYALTY_FREEZE_RECORD_V1"),
                e.chainId,
                e.registry,
                p.resolver,
                p.collectionId,
                p.revenueClass,
                p.expectedAssignmentHash,
                artistId,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function payoutRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.PayoutDesignation memory p,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_PAYOUT_DESIGNATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.payoutAccount,
                p.previousDesignationRecordHash,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function payoutRecordForAuthority(
        Environment memory e,
        StreamArtistOnboardingTypes.PayoutDesignation memory p,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_PAYOUT_DESIGNATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.payoutAccount,
                p.previousDesignationRecordHash,
                signer,
                authorityClass,
                nonce,
                signedAt
            )
        );
    }

    function attestationDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.Attestation memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistAttestation(address core,uint256 collectionId,uint8 subjectKind,bytes32 subjectId,bytes32 subjectStateHash,bytes32 schemaId,bytes32 statementHash,bytes32 statementURIHash,uint256 nonce,uint64 signedAt)"
                    ),
                    e.core,
                    p.collectionId,
                    p.subjectKind,
                    p.subjectId,
                    p.subjectStateHash,
                    p.schemaId,
                    p.statementHash,
                    keccak256(bytes(p.statementURI)),
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function attestationRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.Attestation memory p,
        bytes32 artistId,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ATTESTATION_RECORD_V1"),
                e.chainId,
                e.registry,
                e.core,
                p.collectionId,
                p.subjectKind,
                p.subjectId,
                p.subjectStateHash,
                p.schemaId,
                p.statementHash,
                keccak256(bytes(p.statementURI)),
                artistId,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function attestationRecordForAuthority(
        Environment memory e,
        StreamArtistOnboardingTypes.Attestation memory p,
        bytes32 artistId,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        AttestationRecordPreimage memory words;
        words.domain = keccak256("6529STREAM_ARTIST_ATTESTATION_RECORD_V1");
        words.chainId = e.chainId;
        words.registry = e.registry;
        words.core = e.core;
        words.collectionId = p.collectionId;
        words.subjectKind = p.subjectKind;
        words.subjectId = p.subjectId;
        words.subjectStateHash = p.subjectStateHash;
        words.schemaId = p.schemaId;
        words.statementHash = p.statementHash;
        words.statementURIHash = keccak256(bytes(p.statementURI));
        words.artistId = artistId;
        words.signer = signer;
        words.authorityClass = authorityClass;
        words.nonce = nonce;
        words.signedAt = signedAt;
        return keccak256(abi.encode(words));
    }

    function ratificationDigest(
        Environment memory e,
        StreamArtistOnboardingTypes.Ratification memory p,
        StreamArtistOnboardingTypes.Authorization memory a
    ) internal pure returns (bytes32) {
        return typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistContentRatification(address core,address metadataContract,uint256 collectionId,bytes32 contentStateHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    p.metadataContract,
                    p.collectionId,
                    p.contentStateHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function ratificationRecord(
        Environment memory e,
        StreamArtistOnboardingTypes.Ratification memory p,
        bytes32 artistId,
        address signer,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_CONTENT_RATIFICATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.metadataContract,
                e.core,
                p.collectionId,
                p.contentStateHash,
                artistId,
                signer,
                uint8(1),
                nonce,
                signedAt
            )
        );
    }

    function ratificationRecordForAuthority(
        Environment memory e,
        StreamArtistOnboardingTypes.Ratification memory p,
        bytes32 artistId,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_CONTENT_RATIFICATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.metadataContract,
                e.core,
                p.collectionId,
                p.contentStateHash,
                artistId,
                signer,
                authorityClass,
                nonce,
                signedAt
            )
        );
    }

    function deploymentFacts(
        Environment memory e,
        uint256 collectionId,
        StreamArtistOnboardingTypes.Binding memory b
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DEPLOYMENT_FACTS_V1"),
                e.chainId,
                e.core,
                collectionId,
                b.artistId,
                b.generation,
                b.bindingHash
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistEconomicOperations.sol";
import "./StreamArtistRecordPublicationReads.sol";
import "./StreamArtistAttestationSubjectReads.sol";
import {
    StreamArtistAttestationTypes as Attest,
    IStreamArtistAttestationIdentityOwner,
    IStreamArtistAuthenticatedAttestationOwner
} from "../../interfaces/stream/artist/IStreamArtistAttestationWriter.sol";

/// @notice Original op24 authorization with authenticated subject owners and optional original delegation.
library StreamArtistAttestationOperations {
    function attest(
        D.CoordinatorContext memory x,
        address actor,
        T.Attestation memory p,
        Attest.Subject memory subject,
        bool scoped,
        bytes32 grant,
        T.Authorization memory submitted,
        bytes memory statement
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 24);
        T.Binding memory b = StreamArtistRecordPublicationReads.binding(x.suite, p.collectionId);
        if (!IStreamCoreCollectionView(x.suite.core).collectionExists(p.collectionId)) {
            revert T.InvalidAttribution(p.collectionId);
        }
        Attest.Admission memory admission;
        admission.authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        D.Record memory delegation;
        address signer = admission.authority.authorityAddress;
        if (grant != 0) {
            delegation = IStreamArtistDelegationOwner(x.suite.owners[2]).delegationRecord(grant);
            signer = delegation.grant.delegate;
        }
        bytes memory subjectEvidence;
        if (p.subjectKind <= 6) {
            (admission.fact, subjectEvidence) =
                StreamArtistAttestationSubjectReads.read(x.suite, p, subject, scoped);
        } else {
            if (scoped) revert T.UnsupportedProfile();
            if (p.subjectKind == 7 || p.subjectKind == 8) {
                (P.Publication memory publication,) =
                    StreamArtistRecordPublicationRules.decode(p, statement);
                if (publication.recorder != signer) revert T.InvalidRecord();
                bytes32 runtime = StreamArtistRecordPublicationReads.candidate(x.suite, publication);
                admission.fact =
                    Attest.Fact(publication.metadataHost, runtime, p.subjectId, p.subjectStateHash);
                subjectEvidence = abi.encode(publication, runtime);
            } else if (p.subjectKind == 9) {
                admission.fact = Attest.Fact(
                    x.suite.core,
                    x.suite.core.codehash,
                    p.subjectId,
                    StreamArtistHashes.deploymentFacts(_environment(x), p.collectionId, b)
                );
            } else if (p.subjectKind == 10) {
                admission.operativeIdentity = IStreamArtistIdentityRevisionReads(x.suite.owners[2])
                    .operativeIdentityRecord(b.artistId);
                admission.fact = Attest.Fact(
                    x.suite.owners[2],
                    x.suite.owners[2].codehash,
                    b.artistId,
                    admission.operativeIdentity
                );
            } else {
                revert T.UnsupportedProfile();
            }
        }
        T.Authorization memory effective = _directTime(actor, signer, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistHashes.attestationDigest(_environment(x), p, effective),
            effective.signature
        );
        admission.signer = signer;
        admission.nonce = effective.nonce;
        admission.signedAt = effective.time;
        admission.delegation = grant;
        if (grant == 0) {
            record = IStreamArtistIdentityOwner(x.suite.owners[2])
                .consumeAttestation(T.ActionContext(24, actor, before_[2]), b, p, effective, proof);
        } else {
            record = IStreamArtistAttestationIdentityOwner(x.suite.owners[2])
                .consumeDelegatedAttestation(
                    T.ActionContext(24, actor, before_[2]), b, p, grant, effective, proof
                );
        }
        bytes32 actual = IStreamArtistAuthenticatedAttestationOwner(x.suite.owners[4])
            .recordAuthenticatedAttestation(
                T.ActionContext(24, actor, before_[4]), b, p, admission, statement
            );
        if (actual != record) revert T.InvalidRecord();
        _archive(
            x,
            24,
            actor,
            record,
            before_,
            abi.encode(
                b,
                p,
                submitted,
                effective,
                proof,
                statement,
                subject,
                scoped,
                admission,
                delegation,
                subjectEvidence
            )
        );
    }

    function _directTime(address actor, address signer, T.Authorization memory submitted)
        private
        view
        returns (T.Authorization memory effective)
    {
        effective = T.Authorization(submitted.nonce, submitted.time, submitted.signature);
        if (
            actor == signer && actor != address(0) && submitted.signature.length == 0
                && submitted.time == 0
        ) {
            if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
            effective.time = uint64(block.timestamp);
        }
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                failure != 2 || revision == 0
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) revert T.InvalidSignature();
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x, uint16 op)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        uint256 mask = op == 25 ? 0x04 : 0x17;
        for (uint256 i; i < 7; ++i) {
            if ((mask & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 record,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                record
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1), x.configurationHash, op, actor, record, before_, _snapshots(x, op), payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistAttestationTypes as Attest
} from "../../interfaces/stream/artist/IStreamArtistAttestationWriter.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import "../../interfaces/stream/artist/IStreamArtistFinalityBinding.sol";
import "../../interfaces/stream/artist/IStreamArtistPrimaryScopeFacts.sol";
import "../../interfaces/stream/artist/IStreamArtistRoyaltyScopeFacts.sol";
import "../../interfaces/stream/core/IStreamCorePointers.sol";
import "../../interfaces/stream/mint/IStreamMintReads.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/metadata/IStreamCollectionManifestReads.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/finality/IStreamFinalityDeploymentBindings.sol";
import "../../interfaces/stream/finality/IStreamFinalityDiscoverySources.sol";
import "../finality/StreamFinalityNativeProviderReads.sol";

// Selector projections of actual owner APIs. Absence/malformed replies fail; no fallback hash.
interface IStreamArtistSnapshotConfiguration {
    function nativeConfiguration()
        external
        view
        returns (StreamFinalityNativeProviderReads.Config memory);
}

/// @notice Exact admitted subject owners for original AA-ATTEST kinds 1 through 6.
/// @dev Signatures bind the original subject ID/hash; descriptors only locate those facts.
library StreamArtistAttestationSubjectReads {
    error AttestationSubjectRead(address owner, bytes4 selector);
    error AttestationSubjectGas(uint256 available);

    function read(
        T.SuiteConfiguration memory s,
        T.Attestation memory p,
        Attest.Subject memory q,
        bool scoped
    ) public view returns (Attest.Fact memory f, bytes memory evidence) {
        if (p.subjectKind == 0 || p.subjectKind > 6 || p.schemaId == 0) {
            revert T.UnsupportedProfile();
        }
        if (
            !scoped
                && (q.scopeType != 0
                    || q.tokenId != 0
                    || q.scopeId != 0
                    || q.resolver != address(0))
        ) {
            revert T.InvalidRecord();
        }
        if (scoped && p.subjectKind != 4 && p.subjectKind != 6) revert T.UnsupportedProfile();
        if (p.subjectKind == 1) {
            (f, evidence) = _snapshot(s, p);
        } else if (p.subjectKind == 2 || p.subjectKind == 3) {
            address owner = _selected(s.core, keccak256("COLLECTION_METADATA"), address(0));
            if (
                abi.decode(
                            _fixed(
                                s,
                                owner,
                                abi.encodeCall(IStreamCollectionManifestReads.core, ()),
                                32
                            ),
                            (address)
                        ) != s.core || p.subjectId != bytes32(p.collectionId)
            ) revert T.InvalidRecord();
            bytes memory input = p.subjectKind == 2
                ? abi.encodeCall(
                    IStreamCollectionManifestReads.scriptManifestHash, (p.collectionId)
                )
                : abi.encodeCall(IStreamCollectionManifestReads.mediaManifestHash, (p.collectionId));
            bytes32 hash = abi.decode(_fixed(s, owner, input, 32), (bytes32));
            f = Attest.Fact(owner, owner.codehash, bytes32(p.collectionId), hash);
            evidence = abi.encode(p.subjectKind, f);
        } else if (p.subjectKind == 4) {
            (f, evidence) = _finality(s, p, q, scoped);
        } else if (p.subjectKind == 5) {
            if (address(IStreamMintReads(s.mintManager).core()) != s.core) {
                revert T.ComponentChanged(s.mintManager);
            }
            (bool exists,) = IStreamMintReads(s.mintManager).phase(p.collectionId, p.subjectId);
            if (!exists || p.subjectId == 0) revert T.InvalidRecord();
            f = Attest.Fact(
                s.mintManager,
                s.mintManager.codehash,
                p.subjectId,
                abi.decode(
                    _fixed(
                        s,
                        s.mintManager,
                        abi.encodeCall(
                            IStreamMintReads.phasePolicyHash, (p.collectionId, p.subjectId)
                        ),
                        32
                    ),
                    (bytes32)
                )
            );
            evidence = abi.encode(f);
        } else {
            (f, evidence) = _economics(s, p, q, scoped);
        }
        if (
            f.owner.code.length == 0 || f.ownerCodeHash != f.owner.codehash || f.stateHash == 0
                || f.subjectId != p.subjectId || f.stateHash != p.subjectStateHash
        ) revert T.InvalidRecord();
    }

    function _snapshot(T.SuiteConfiguration memory s, T.Attestation memory p)
        private
        view
        returns (Attest.Fact memory f, bytes memory evidence)
    {
        address registry = _registry(s);
        IStreamFinalityDeploymentBindings finality = IStreamFinalityDeploymentBindings(registry);
        address provider = finality.scopeEvidenceProvider();
        if (
            provider.code.length == 0
                || provider.codehash != finality.scopeEvidenceProviderCodeHash()
        ) {
            revert T.ComponentChanged(provider);
        }
        address host = IStreamFinalityDiscoverySources(provider).snapshotHost();
        StreamFinalityNativeProviderReads.Config memory c = abi.decode(
            _fixed(
                s,
                provider,
                abi.encodeCall(IStreamArtistSnapshotConfiguration.nativeConfiguration, ()),
                1568
            ),
            (StreamFinalityNativeProviderReads.Config)
        );
        if (
            c.chainId != block.chainid || c.targets[0] != s.core || c.targets[2] != s.metadata
                || c.targets[11] != s.registry || c.targets[12] != registry || c.targets[8] != host
                || host.code.length == 0 || c.codeHashes[8] == 0 || host.codehash != c.codeHashes[8]
        ) {
            revert T.ComponentChanged(host);
        }
        IStreamCollectionSnapshots owner = IStreamCollectionSnapshots(host);
        if (owner.core() != s.core || owner.metadataRouter() != s.metadata) {
            revert T.ComponentChanged(host);
        }
        StreamSnapshotTypes.Receipt memory r = abi.decode(
            _fixed(
                s,
                host,
                abi.encodeCall(IStreamCollectionSnapshots.currentSnapshot, (p.collectionId)),
                672
            ),
            (StreamSnapshotTypes.Receipt)
        );
        if (
            r.collectionId != p.collectionId || r.snapshotId == 0 || r.snapshotId != p.subjectId
                || r.recordHash == 0 || r.revision == 0 || r.manifestHash == 0
                || r.manifestHash
                    != abi.decode(
                        _fixed(
                            s,
                            host,
                            abi.encodeCall(
                                IStreamCollectionSnapshots.latestSnapshotHash, (p.collectionId)
                            ),
                            32
                        ),
                        (bytes32)
                    )
                || r.manifestHash
                    != abi.decode(
                        _fixed(
                            s,
                            host,
                            abi.encodeCall(
                                IStreamCollectionSnapshots.snapshotHash,
                                (p.collectionId, r.snapshotId)
                            ),
                            32
                        ),
                        (bytes32)
                    )
        ) revert T.InvalidRecord();
        f = Attest.Fact(host, c.codeHashes[8], r.snapshotId, r.manifestHash);
        evidence = abi.encode(registry, provider, provider.codehash, r);
    }

    function _finality(
        T.SuiteConfiguration memory s,
        T.Attestation memory p,
        Attest.Subject memory q,
        bool scoped
    ) private view returns (Attest.Fact memory f, bytes memory evidence) {
        address registry = _registry(s);
        if (q.resolver != address(0) || q.scopeType > 4) revert T.UnsupportedProfile();
        StreamFinalityScope memory scope = StreamFinalityScope(
            StreamFinalityScopeType(q.scopeType), p.collectionId, q.tokenId, q.scopeId
        );
        if (
            (q.scopeType == 0 && (q.tokenId != 0 || q.scopeId != 0))
                || (q.scopeType == 1 && (q.tokenId == 0 || q.scopeId != 0))
                || (q.scopeType >= 2 && (q.tokenId != 0 || q.scopeId == 0))
        ) revert T.InvalidRecord();
        bytes32 key = scoped
            ? keccak256(
                abi.encode(keccak256("6529STREAM_ARTIST_FINALITY_ATTESTATION_SUBJECT_V1"), scope)
            )
            : bytes32(p.collectionId);
        bytes32 hash;
        if (q.scopeType == 0) {
            StreamCollectionFinalityRecord memory r =
                IStreamArtworkFinalityRegistry(registry).collectionFinalityRecord(p.collectionId);
            if (!r.finalized || r.finalizedAt == 0 || r.finalizedAt > block.timestamp) {
                revert T.InvalidRecord();
            }
            hash = r.finalityRecordHash;
            evidence = abi.encode(scope, r);
        } else {
            StreamScopedFinalityRecord memory r =
                IStreamArtworkFinalityRegistry(registry).artworkScopeFinalityRecord(scope);
            if (
                !r.finalized || r.finalizedAt == 0 || r.finalizedAt > block.timestamp
                    || keccak256(abi.encode(r.scope)) != keccak256(abi.encode(scope))
            ) revert T.InvalidRecord();
            hash = r.finalityRecordHash;
            evidence = abi.encode(r);
        }
        f = Attest.Fact(registry, registry.codehash, key, hash);
    }

    function _economics(
        T.SuiteConfiguration memory s,
        T.Attestation memory p,
        Attest.Subject memory q,
        bool scoped
    ) private view returns (Attest.Fact memory f, bytes memory evidence) {
        address resolver = scoped ? q.resolver : address(uint160(uint256(p.subjectId)));
        if (resolver != s.primaryResolver && resolver != s.royaltyResolver) {
            revert T.ComponentChanged(resolver);
        }
        if (!scoped && bytes32(uint256(uint160(resolver))) != p.subjectId) {
            revert T.InvalidRecord();
        }
        if (
            scoped
                && (q.scopeType > 2
                    || q.tokenId != 0
                    || (q.scopeType == 0 && q.scopeId != 0)
                    || (q.scopeType == 1 && uint256(q.scopeId) != p.collectionId)
                    || (q.scopeType == 2 && q.scopeId == 0))
        ) revert T.InvalidRecord();
        T.AssignmentFact memory a;
        if (resolver == s.primaryResolver) {
            if (IStreamRevenueResolver(resolver).core() != s.core) {
                revert T.ComponentChanged(resolver);
            }
            IStreamRevenueResolver.ResolvedPrimaryAssignment memory r = scoped
                ? IStreamArtistPrimaryScopeFacts(resolver)
                    .primaryEconomicsFacts(p.collectionId, q.scopeType, uint256(q.scopeId))
                : IStreamRevenueResolver(resolver)
                    .resolvePrimaryAssignment(p.collectionId, 0, s.primaryRevenueClass);
            if (!r.exists) revert T.InvalidRecord();
            a = T.AssignmentFact(
                resolver, s.primaryRevenueClass, r.scope, r.scopeId, r.assignmentHash
            );
            evidence = abi.encode(r);
        } else {
            _selected(s.core, keccak256("ROYALTY_RESOLVER"), resolver);
            IStreamRoyaltyResolver.RoyaltyConfig memory config;
            if (scoped) {
                (a, config) = IStreamArtistRoyaltyScopeFacts(resolver)
                    .royaltyEconomicsFacts(p.collectionId, q.scopeType, uint256(q.scopeId));
            } else {
                (a, config,) = IStreamArtistRoyaltyScopeFacts(resolver)
                    .resolveRoyaltyAssignment(p.collectionId, 0);
            }
            if (
                !config.configured || a.resolver != resolver
                    || a.revenueClass != keccak256("ROYALTY_ERC2981")
            ) revert T.InvalidRecord();
            evidence = abi.encode(a, config);
        }
        if (scoped && (a.scope != q.scopeType || a.scopeId != uint256(q.scopeId))) {
            revert T.InvalidRecord();
        }
        bytes32 key = scoped
            ? keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_ECONOMICS_ATTESTATION_SUBJECT_V1"),
                    p.collectionId,
                    resolver,
                    a.revenueClass,
                    a.scope,
                    a.scopeId
                )
            )
            : p.subjectId;
        f = Attest.Fact(resolver, resolver.codehash, key, a.assignmentHash);
    }

    function _fixed(T.SuiteConfiguration memory s, address target, bytes memory input, uint256 size)
        private
        view
        returns (bytes memory result)
    {
        (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(s.registry)
            .gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_RECORD_PUBLICATION_READ_GAS"));
        if (cap == 0 || cap > type(uint256).max / 2 || failure != 2 || revision == 0) {
            revert T.InvalidBinding();
        }
        result = new bytes(size);
        uint256 available = gasleft();
        if (available <= 105000) revert AttestationSubjectGas(available);
        uint256 forwarded = available - 105000;
        if (cap < forwarded) forwarded = cap;
        bool ok;
        uint256 actual;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(input, 32), mload(input), add(result, 32), size)
            actual := returndatasize()
        }
        if (!ok || actual != size) revert AttestationSubjectRead(target, bytes4(input));
    }

    function _registry(T.SuiteConfiguration memory s) private view returns (address r) {
        r = IStreamArtistFinalityBinding(s.registry).finalityRegistry();
        if (
            r.code.length == 0
                || r.codehash != IStreamArtistFinalityBinding(s.registry).finalityRegistryCodeHash()
        ) revert T.ComponentChanged(r);
    }

    function _selected(address core, bytes32 kind, address expected)
        private
        view
        returns (address target)
    {
        bytes32 hash;
        (target, hash,,,,,,,,) = IStreamCorePointers(core).getSatellitePointer(kind);
        if (
            target.code.length == 0 || hash == 0 || target.codehash != hash
                || (expected != address(0) && target != expected)
        ) revert T.ComponentChanged(target);
    }
}

