pragma solidity ^0.8.19;

import "./StreamArtistHashes.sol";
import "./StreamArtistNonceAvailability.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";

/// @notice Linked implementation operating only on Identity's appended delegation storage.
/// @dev No independent authority or record store. Identity checks Coordinator/snapshot and commits every returned delta.
library StreamArtistDelegationState {
    using StreamArtistNonceAvailability for StreamArtistNonceAvailability.Index;

    struct State {
        mapping(bytes32 => D.Record) records;
        mapping(bytes32 => bytes32) current;
        mapping(bytes32 => StreamArtistNonceAvailability.Index) availability;
        mapping(bytes32 => uint256) hints;
    }

    function grantDigest(StreamArtistHashes.Environment memory e, D.Grant memory p, uint256 nonce)
        public
        pure
        returns (bytes32)
    {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistDelegation(address core,address delegate,uint256 collectionId,uint32 capabilities,uint64 notBefore,uint64 expiresAt,uint64 maxUses,bytes32 constraintsHash,uint256 nonce)"
                    ),
                    e.core,
                    p.delegate,
                    p.collectionId,
                    p.capabilities,
                    p.notBefore,
                    p.expiresAt,
                    p.maxUses,
                    p.constraintsHash,
                    nonce
                )
            )
        );
    }

    function revokeDigest(
        StreamArtistHashes.Environment memory e,
        D.Revocation memory p,
        uint256 nonce,
        uint64 deadline
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistDelegationRevocation(bytes32 artistId,address delegate,bytes32 delegationRecordHash,bytes32 reasonHash,uint256 nonce,uint64 deadline)"
                    ),
                    p.artistId,
                    p.delegate,
                    p.delegationRecordHash,
                    p.reasonHash,
                    nonce,
                    deadline
                )
            )
        );
    }

    function grant(
        State storage s,
        StreamArtistHashes.Environment memory e,
        D.Grant memory p,
        address grantor,
        uint256 nonce
    ) public returns (bytes32 record, bytes32 delta) {
        if (
            p.artistId == bytes32(0) || p.delegate == address(0) || p.delegate == grantor
                || p.capabilities == 0 || (p.capabilities & ~uint32(1143)) != 0
                || p.expiresAt <= p.notBefore || block.timestamp >= p.expiresAt
        ) revert T.UnsupportedProfile();
        bytes32 scope = keccak256(abi.encode(p.artistId, p.delegate));
        bytes32 prior = s.current[scope];
        D.Record storage old = s.records[prior];
        // Future grants reserve the key too. A revoked/expired/exhausted grant can be replaced.
        if (
            old.grantor != address(0) && !old.revoked && block.timestamp < old.grant.expiresAt
                && (old.grant.maxUses == 0 || old.uses < old.grant.maxUses)
        ) revert D.ConflictingDelegation(prior);
        record = _grantRecord(e, p, nonce);
        if (s.records[record].grantor != address(0)) revert D.InvalidDelegation(record);
        s.records[record] = D.Record(p, grantor, nonce, 0, false, bytes32(0));
        s.current[scope] = record;
        delta = keccak256(abi.encode(scope, prior, record, s.records[record]));
    }

    function _grantRecord(StreamArtistHashes.Environment memory e, D.Grant memory p, uint256 nonce)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DELEGATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.delegate,
                p.collectionId,
                p.capabilities,
                p.notBefore,
                p.expiresAt,
                p.maxUses,
                p.constraintsHash,
                nonce
            )
        );
    }

    function revoke(
        State storage s,
        StreamArtistHashes.Environment memory e,
        D.Revocation memory p,
        address signer,
        uint256 nonce,
        uint64 time
    ) public returns (bytes32 record, bytes32 delta) {
        D.Record storage item = s.records[p.delegationRecordHash];
        if (
            item.grantor == address(0) || item.revoked || item.grantor != signer
                || item.grant.artistId != p.artistId || item.grant.delegate != p.delegate
        ) revert D.InvalidDelegation(p.delegationRecordHash);
        record = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DELEGATION_REVOCATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.delegate,
                p.delegationRecordHash,
                signer,
                uint8(1),
                p.reasonHash,
                nonce,
                time
            )
        );
        item.revoked = true;
        item.revocationRecordHash = record;
        delta = keccak256(abi.encode(p.delegationRecordHash, item));
    }

    function lane(bytes32 artistId, address delegate) public pure returns (bytes32) {
        return keccak256(
            abi.encode(keccak256("6529STREAM_ARTIST_DELEGATE_NONCE_LANE_V1"), artistId, delegate)
        );
    }

    function active(D.Record memory item) public view returns (bool) {
        return item.grantor != address(0) && !item.revoked
            && block.timestamp >= item.grant.notBefore && block.timestamp < item.grant.expiresAt
            && (item.grant.maxUses == 0 || item.uses < item.grant.maxUses);
    }

    function consume(
        State storage s,
        bytes32 record,
        bytes32 artistId,
        uint256 collectionId,
        uint32 capability,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        address actor,
        bytes32 digest
    ) public returns (bytes32 replayLane, bytes32 delta) {
        D.Record storage item = s.records[record];
        if (!active(item)) revert D.DelegationUnavailable(record);
        if (
            item.grant.artistId != artistId
                || (item.grant.collectionId != 0 && item.grant.collectionId != collectionId)
        ) revert D.DelegationScope(record);
        if ((item.grant.capabilities & capability) == 0) {
            revert D.DelegationCapability(record, capability);
        }
        if (
            proof.signer != item.grant.delegate || proof.digest != digest
                || (proof.direct && (actor != proof.signer || a.signature.length != 0))
                || (!proof.direct && a.signature.length == 0 && proof.signer.code.length == 0)
        ) revert T.InvalidSignature();
        if (a.signature.length > 4096) revert T.BoundExceeded(a.signature.length, 4096);
        replayLane = lane(artistId, proof.signer);
        delta = _consume(s, record, replayLane, a.nonce, proof.direct);
    }

    function _consume(
        State storage s,
        bytes32 record,
        bytes32 replayLane,
        uint256 nonce,
        bool direct
    ) private returns (bytes32 delta) {
        if (direct && nonce != s.hints[replayLane]) revert T.InvalidRecord();
        bytes32 availabilityDelta = s.availability[replayLane].consumeTagged(nonce, 2, replayLane);
        if (nonce == s.hints[replayLane]) {
            (, s.hints[replayLane]) = s.availability[replayLane].firstUnused();
        }
        D.Record storage item = s.records[record];
        ++item.uses;
        delta = keccak256(
            abi.encode(record, item, replayLane, nonce, s.hints[replayLane], availabilityDelta)
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";

import "./StreamArtistIdentityState.sol";
import "../../interfaces/stream/artist/IStreamArtistAuthorizationRevocation.sol";

/// @notice Linked operation-54 mechanics; Identity retains the typed guard and single semantic commit.
library StreamArtistAuthorizationState {
    using StreamArtistNonceAvailability for StreamArtistNonceAvailability.Index;

    event ArtistAuthorizationRevoked(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        bytes32 revokedDigest,
        uint256 revokedNonce,
        uint256 nonce,
        uint64 revokedAt,
        bytes32 revocationRecordHash
    );

    function digest(
        StreamArtistHashes.Environment memory e,
        StreamArtistAuthorizationTypes.Revocation memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistAuthorizationRevocation(bytes32 artistId,bytes32 revokedDigest,uint256 revokedNonce,uint256 nonce,uint64 deadline)"
                    ),
                    p.artistId,
                    p.revokedDigest,
                    p.revokedNonce,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function authorizationState(
        StreamArtistIdentityState.State storage identity,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        bytes32 artistId,
        bytes32 actionDigest,
        uint256 nonce
    ) public view returns (StreamArtistAuthorizationTypes.State memory result) {
        result.digestObserved = replay[_key(
                    o,
                    keccak256("identity_authority.replay.authorization_consumed_digest"),
                    keccak256(abi.encode(artistId, actionDigest))
                )].status != 0;
        result.digestRevoked = replay[_key(
                    o,
                    keccak256("identity_authority.replay.digest_revocation"),
                    keccak256(abi.encode(artistId, actionDigest))
                )].status != 0;
        result.nonceConsumed = replay[_key(
                    o,
                    keccak256("identity_authority.replay.nonce_allocator"),
                    keccak256(abi.encode(artistId, nonce))
                )].status != 0;
        result.nonceRevoked = replay[_targetKey(o, artistId, bytes32(0), nonce)].status != 0;
        result.nextUnusedNonce = identity.identities[artistId].nonceHint;
    }

    function revoke(
        StreamArtistIdentityState.State storage identity,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        StreamArtistAuthorizationTypes.Revocation memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        if (p.artistId == bytes32(0) || (p.revokedDigest == bytes32(0)) == (p.revokedNonce == 0)) {
            revert T.InvalidRecord();
        }
        if (block.timestamp > a.time) revert T.ExpiredAuthorization(a.time);
        if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
        bytes32 actionDigest = digest(o.environment, p, a);
        if (
            p.revokedDigest == actionDigest
                || (p.revokedDigest == bytes32(0) && p.revokedNonce == a.nonce)
        ) revert T.InvalidRecord();
        bytes32 target = _targetKey(o, p.artistId, p.revokedDigest, p.revokedNonce);
        if (replay[target].status != 0) revert T.Replay(target);
        bytes32 denyKey;
        if (p.revokedDigest != bytes32(0)) {
            bytes32 used = _key(
                o,
                keccak256("identity_authority.replay.authorization_consumed_digest"),
                keccak256(abi.encode(p.artistId, p.revokedDigest))
            );
            if (replay[used].status != 0) revert T.Replay(used);
            denyKey = _key(
                o,
                keccak256("identity_authority.replay.digest_revocation"),
                keccak256(abi.encode(p.artistId, p.revokedDigest))
            );
        } else {
            denyKey = _key(
                o,
                keccak256("identity_authority.replay.nonce_allocator"),
                keccak256(abi.encode(p.artistId, p.revokedNonce))
            );
        }
        if (replay[denyKey].status != 0) revert T.Replay(denyKey);
        uint64 observed = uint64(block.timestamp);
        bytes32 record = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_AUTH_REVOCATION_RECORD_V1"),
                o.environment.chainId,
                o.environment.registry,
                p.artistId,
                p.revokedDigest,
                p.revokedNonce,
                a.nonce,
                observed
            )
        );
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
            a,
            proof,
            actionDigest,
            record,
            identity.identities[p.artistId].authorityAddress
        );
        replay[denyKey] = T.ReplayCell(record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(denyKey, replay[denyKey]);
        replay[target] = T.ReplayCell(record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(target, replay[target]);
        bytes32 availability;
        if (p.revokedDigest == bytes32(0)) {
            availability =
                identity.nonceAvailability[p.artistId].consumeTagged(p.revokedNonce, 1, p.artistId);
            if (identity.identities[p.artistId].nonceHint == p.revokedNonce) {
                (, identity.identities[p.artistId].nonceHint) =
                    identity.nonceAvailability[p.artistId].firstUnused();
            }
        }
        m.action = keccak256(abi.encode(m.action, p, record));
        m.state = keccak256(
            abi.encode(
                m.state, p.artistId, identity.identities[p.artistId].nonceHint, target, record
            )
        );
        m.replay = keccak256(abi.encode(m.replay, denyKey, target, record, availability));
        m.record = record;
        emit ArtistAuthorizationRevoked(
            1, p.artistId, p.revokedDigest, p.revokedNonce, a.nonce, observed, record
        );
    }

    function _targetKey(
        StreamArtistIdentityState.OwnerContext memory o,
        bytes32 artistId,
        bytes32 targetDigest,
        uint256 nonce
    ) private view returns (bytes32) {
        return _key(
            o,
            keccak256("identity_authority.replay.target_authorization_revocation"),
            keccak256(abi.encode(artistId, targetDigest, nonce))
        );
    }

    function _key(StreamArtistIdentityState.OwnerContext memory o, bytes32 surface, bytes32 scope)
        private
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                scope
            )
        );
    }
}
